const names={publications:['发文趋势','Publications'],keywords:['关键词共现','Co-occurrence'],clusters:['聚类视图','Clusters'],timezone:['时区视图','Time zone'],timeline:['时间线','Timeline'],landscape:['聚类演化','Landscape'],bursts:['突现词','Bursts'],authors:['作者合作','Authors'],institutions:['机构合作','Institutions']};
