function tableTitle(file){return (tableNames[file]?.[language==='en'?1:0]||file)+' · '+file;}
function renderTable(){const query=$('table-search').value.toLowerCase();const rows=tableRows.slice(1).filter(row=>!query||row.some(v=>v.toLowerCase().includes(query)));const table=document.createElement('table');if(tableRows.length){const tr=document.createElement('tr'),head=document.createElement('thead');for(const value of tableRows[0]){const th=document.createElement('th');th.textContent=columnNames[value]?.[language==='en'?1:0]||value;th.title=value;tr.append(th);}head.append(tr);table.append(head);const body=document.createElement('tbody');for(const row of rows.slice(0,300)){const tr=document.createElement('tr');for(const value of row){const td=document.createElement('td');td.textContent=value;td.title=value;tr.append(td);}body.append(tr);}table.append(body);}$('table-container').replaceChildren(table);$('table-note').textContent=t(`${rows.length} 行；最多预览 300 行，下载获得完整数据。`,`${rows.length} rows; up to 300 previewed. Download the full data.`);}
async function loadNodes(job,file,key){const r=await fetch(reportBase(job)+'data/'+file);if(!r.ok)return;const lines=(await r.text()).trimEnd().split(/\r?\n/).map(l=>l.split('\t'));if(nodeKey!==key)return;const headers=lines.shift();nodeRows=lines.map(values=>Object.fromEntries(headers.map((name,i)=>[name,values[i]||'']))).sort((a,b)=>Number(b.freq)-Number(a.freq));renderNodes();}
function renderNodes(){const query=$('node-search').value.toLowerCase();$('node-list').replaceChildren();for(const node of nodeRows.filter(n=>(n.label||n.id).toLowerCase().includes(query)).slice(0,40)){const button=document.createElement('button');button.className='node-row';button.classList.toggle('active',inspectedNode?.id===node.id);const name=document.createElement('span');name.textContent=node.label||node.id;name.title=name.textContent;const count=document.createElement('strong');count.textContent=node.freq;button.append(name,count);button.onclick=()=>inspectNode(node);$('node-list').append(button);}if(!nodeRows.length){const empty=document.createElement('p');empty.className='muted small';empty.textContent=t('分析后显示节点。','Nodes appear after analysis.');$('node-list').append(empty);}}
function inspectNode(node){inspectedNode=node;$('node-detail').hidden=false;$('node-detail').replaceChildren();const heading=document.createElement('h3');heading.textContent=node.label||node.id;$('node-detail').append(heading);for(const[label,value]of [[t('频次','Frequency'),node.freq],[t('中介中心性','Betweenness'),node.centrality],[t('图中聚类编号','Display cluster'),Number(node.cluster)>0?'#'+(Number(node.cluster)-1):t('未归类','Unassigned')],[t('首次出现','First appearance'),node.first_year]]){const row=document.createElement('div');row.className='metric-row';const name=document.createElement('span');name.textContent=label;const val=document.createElement('strong');val.textContent=value;row.append(name,val);$('node-detail').append(row);}}
async function startJob(charts=[selectedKey]){if(submitting||jobs.some(j=>j.status==='running'))return;if(!inputs.length){notice(t('请先导入文献。','Import literature first.'));return;}submitting=true;updateButtons();try{const validated=await api('validate-settings',{settings:{...(charts.length===1?parametersForView(charts[0]):settings),charts,language}});const value=await api('run',{inputs,output:$('output').value.trim(),settings:validated.result});selectedJob=value.id;rememberMetadata({inputs:[...inputs],view:selectedKey,output:$('output').value}).catch(()=>{});lastRequest={id:value.id,charts:[...charts]};analysisDirty=false;nodeKey='';$('node-detail').hidden=true;await refresh();}finally{submitting=false;updateButtons();}}
async function upload(files){if(!files.length)return;if([...files].reduce((n,f)=>n+f.size,0)>23*1024*1024)throw new Error(t('文件超过 23 MB，请选择本地目录。','Files exceed 23 MB; use a local folder.'));const payload=[];for(const file of files){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));payload.push({name:file.name,data:btoa(binary)});}const value=await api('upload',{files:payload});setInputs(value.inputs);}
function renderQuickSettings(){const host=$('quick-settings');host.replaceChildren();const fields=[['network','网络类型','Network type','select',['keyword','term','author','institution','cocitation','coupling','aca','jca','country','category']],['from_year','开始年份','Start year','number'],['to_year','结束年份','End year','number'],['slice_years','时间切片（年）','Years per slice','number'],['selection','节点选择','Node selection','select',['gindex','topn','topnpct']],['g_index_k','g-index 倍率 k','g-index factor k','number'],['per_slice','每片选取数（0 为全局）','Nodes per slice (0 = global)','number'],['top_n','全局最多节点（0 不限）','Global node limit (0 = all)','number'],['top_percent','每片保留百分比','Selected per slice (%)','number'],['pruning','剪枝','Pruning','select',['none','mst','pathfinder']],['clustering','聚类方法','Clustering','select',['modularity','spectral','em']],['label_scale','标签大小','Label size','number'],['node_scale','节点大小','Node size','number'],['link_opacity','连线不透明度','Link opacity','number']];const labels={keyword:['关键词','Keywords'],term:['题名 / 摘要术语','Title / abstract terms'],author:['作者','Authors'],institution:['机构','Institutions'],cocitation:['文献共被引','Document co-citation'],coupling:['文献耦合','Bibliographic coupling'],aca:['作者共被引','Author co-citation'],jca:['期刊共被引','Journal co-citation'],country:['国家 / 地区','Countries'],category:['学科','Categories'],none:['不剪枝','None'],mst:['最小生成树','MST'],pathfinder:['Pathfinder','Pathfinder'],gindex:['g-index','g-index'],topn:['Top N','Top N'],topnpct:['Top N%','Top N%'],modularity:['模块度优化','Modularity'],spectral:['谱聚类','Spectral'],em:['EM 聚类','EM']};
 for(const[key,zh,en,type,options]of fields){if(key==='g_index_k'&&settings.selection!=='gindex'||key==='per_slice'&&settings.selection!=='topn'||key==='top_percent'&&settings.selection!=='topnpct'||key==='top_n'&&settings.selection==='gindex')continue;const field=document.createElement('label');field.className='quick-field';field.textContent=t(zh,en);const input=document.createElement(type==='select'?'select':'input');input.dataset.key=key;input.id='quick-'+key;const help={g_index_k:['k 越大，通常保留越多节点；按当前切片计算。','Larger k usually retains more nodes, within the selected slices.'],pruning:['MST 保留骨架；Pathfinder 减少冗余连接。','MST retains a backbone; Pathfinder removes redundant links.'],slice_years:['每个时间片覆盖的年份数。','Number of years covered by each time slice.'],selection:['选点决定进入网络的节点；不只是显示过滤。','Selection determines which nodes enter the network.'],link_opacity:['0 完全透明，1 完全不透明。','0 is transparent; 1 is opaque.']};if(help[key])input.title=t(...help[key]);if(type==='select')for(const value of options)input.add(new Option(labels[value]?labels[value][language==='en'?1:0]:value,value));else{input.type='number';input.step=['node_scale','label_scale','link_opacity'].includes(key)?'.1':'1';}input.value=settings[key];if(['from_year','to_year'].includes(key)){input.placeholder=t('自动','Auto');if(!settings[key])input.value='';input.min='0';}if(key==='link_opacity'){input.min='0';input.max='1';}if(key==='network'&&names[selectedKey]){input.disabled=true;input.title=t('该视图使用固定的分析对象；更多视图可选择网络类型。','This view has a dedicated network type; additional views use the network selector.');input.value=selectedKey==='authors'?'author':selectedKey==='institutions'?'institution':'keyword';}input.onchange=safely(async()=>{const value=type==='number'?Number(input.value):input.value;try{settings=await rememberSettings(()=>({...settings,[key]:value}));analysisDirty=true;updateSettingsSummary();}catch(e){input.value=settings[key];throw e;}});field.append(input);host.append(field);}}

