const textMemory=new WeakMap(),attributeMemory=new WeakMap();
function translated(value){
 const source=value.trim();if(language!=="en")return value;
 const exact=uiEnglish[source];if(exact)return value.replace(source,exact);
 return value.replace(/已完成 · /g,"Completed · ").replace(/ 条无年份文献未计入/g," undated records excluded")
   .replace(/已选择 (\d+) 个输入 · 每年一片 · g-index k=25/g,"$1 inputs selected · one-year slices · g-index k=25")
   .replace(/(\d+) 行，预览前 300 行；下载可获得完整数据/g,"$1 rows; previewing the first 300. Download the full data.")
   .replace(/(\d+) 行/g,"$1 rows");
}
function translateUI(){
 document.documentElement.lang=language==="en"?"en":"zh-CN";document.title=t("Ycscite · 文献计量工作台","Ycscite · Bibliometric workbench");$("report-frame").title=t("分析结果总览","Analysis result overview");$("generate-nine").title=t("使用当前数据和分析参数，生成全部九种常用图谱。","Generate all nine standard charts using the current data and analysis settings.");
 const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
 const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){
  if(["SCRIPT","STYLE","TEXTAREA","PRE"].includes(node.parentElement?.tagName)||node.parentElement?.closest("tbody"))continue;
  const remembered=textMemory.get(node);const source=remembered&&node.nodeValue===remembered.output?remembered.source:node.nodeValue;
  const output=translated(source);if(node.nodeValue!==output)node.nodeValue=output;textMemory.set(node,{source,output});
 }
 for(const el of document.querySelectorAll("[placeholder],[aria-label],[alt]")){
  const memory=attributeMemory.get(el)||{};
  for(const key of ["placeholder","aria-label","alt"]){if(!el.hasAttribute(key))continue;const current=el.getAttribute(key),previous=memory[key];
   const source=previous&&previous.output===current?previous.source:current;const output=translated(source);el.setAttribute(key,output);memory[key]={source,output};}
  attributeMemory.set(el,memory);
 }
}
