function readSettingsForm(){
 const draft={...(settingsDraft||settings)};
 for(const input of $("settings-fields").querySelectorAll("[data-key]"))draft[input.dataset.key]=input.dataset.list?input.value.split(/[,;，；\n]+/).map(v=>v.trim()).filter(Boolean):input.type==="checkbox"?input.checked:input.type==="number"?Number(input.value):input.value;
 draft.charts=[...$("chart-options").querySelectorAll("input:checked")].map(el=>el.dataset.chart);
 draft.analysis_modules=[...$("module-options").querySelectorAll("input:checked")].map(el=>el.dataset.module);
 draft.exports=[...$("export-options").querySelectorAll("input:checked")].map(el=>el.dataset.export);
 if(!draft.charts.length)throw new Error(language==="en"?"Choose at least one chart":"请至少选择一张图");
 if(draft.from_year&&draft.to_year&&draft.from_year>draft.to_year)throw new Error(language==="en"?"Start year must not exceed end year":"开始年份不能晚于结束年份");
 for(const[key,value]of Object.entries(draft))if(typeof value==="number"&&!Number.isFinite(value))throw new Error(`${key}: invalid number`);
 return draft;
}
function updateSettingsSummary(){
 $("settings-summary").textContent=settings.selection==="gindex"?`k = ${settings.g_index_k}`:settings.selection;
 localWrite("ycscite-settings",JSON.stringify(settings));$("download-logo").checked=settings.logo!==false;
 renderQuickSettings();render();
}
async function inspectInputs(){
 if(!inputs.length)return;
 const inspectedInputs=JSON.stringify(inputs);inspectStatus="pending";let result;try{result=await api("inspect",{inputs:[...inputs],format:settings.format||"auto"});}catch(error){if(inspectedInputs!==JSON.stringify(inputs))return;inspectStatus="error";render();throw error;}
 if(inspectedInputs!==JSON.stringify(inputs))return;const info=result.result;previewInfo=info;inspectStatus="ready";$('input-hint').textContent=t('运行分析生成当前图；也可一键生成默认九图。','Run the current view, or generate all nine standard charts.');render();const preview=$("import-preview");preview.hidden=false;
 const missing=!info.records_with_keywords||!info.records_with_references;
 preview.classList.toggle("warning",missing);
 preview.textContent=language==="en"?`${info.records} records · ${info.from_year??"?"}–${info.to_year??"?"} · ${info.undated_records} undated. References: ${info.records_with_references} records.`:
  `${info.records} 篇文献 · ${info.from_year??"?"}–${info.to_year??"?"} · ${info.undated_records} 篇无年份。${info.records_with_references} 篇包含参考文献。`;
 if(!info.records_with_keywords)preview.textContent+=t(' 缺少关键词；可在扩展视图选用题名 / 摘要术语网络。',' No keywords; title/abstract term networks are available in additional views.');
 if(!info.records_with_references)preview.textContent+=language==="en"?" Co-citation and coupling need references.":" 共被引与耦合分析需要参考文献。";
}
function setSettingsTab(tab){settingsTab=tab;for(const el of $("settings-dialog").querySelectorAll("[data-settings-group]"))el.hidden=el.dataset.settingsGroup!==tab;for(const button of $("settings-dialog").querySelectorAll("[data-settings-tab]")){button.classList.toggle("active",button.dataset.settingsTab===tab);button.onclick=()=>{setSettingsTab(button.dataset.settingsTab);};}if(!batchMode)$('chart-options').parentElement.hidden=true;translateUI();}


