async function restoreJob(id){selectedJob=id;const job=current();if(!job)return;setInputs(job.inputs||[]);if(!inputs.length)loadedReportId=id;if(job.manifest?.parameters){settings=await rememberSettings({...capabilities.default_settings,...job.manifest.parameters,language});}if(!job.manifest?.figures.some(f=>f.key===selectedKey)&&job.manifest?.figures.length)selectedKey=job.manifest.figures[0].key;analysisDirty=false;$('download-logo').checked=settings.logo!==false;renderQuickSettings();render();await rememberMetadata({inputs:[...inputs],view:selectedKey,download_logo:$('download-logo').checked});}

async function initialize(){
 const [catalog,savedState]=await Promise.all([api('capabilities'),api('workspace')]);capabilities=catalog;chartRegistry=capabilities.charts;for(const chart of chartRegistry)uiEnglish[chart.title_zh]=chart.title_en;
 const saved=savedState.workspace||{};lastRememberedReportId=saved.report_id||null;let legacy={};try{legacy=JSON.parse(localRead('ycscite-settings')||'{}');}catch{}
 const chosen=savedState.has_saved_state?(saved.settings||{}):legacy;language=savedState.has_saved_state?saved.language:localRead('ycscite-language')||'zh';if(!['zh','en'].includes(language))language='zh';
 settings={...capabilities.default_settings,...Object.fromEntries(Object.entries(chosen).filter(([key])=>key in capabilities.default_settings)),language};
 try{settings=(await api('validate-settings',{settings})).result;}catch{settings={...capabilities.default_settings,language};workspaceSaveStatus='error';notice(t('保存的参数无效，已恢复默认设置；原文件仍保留。','Saved settings were invalid; defaults were restored and the original file was retained.'));}
 $('language').value=language;$('download-logo').checked=saved.download_logo??settings.logo!==false;selectedKey=chartRegistry.some(c=>c.key===saved.view)?saved.view:'keywords';exportKey=saved.export_format||'png';dataMode=!!saved.data_mode;$('output').value=saved.output||'';
 selectedJob=saved.report_id||null;setInputs(saved.inputs||[]);if(!inputs.length&&selectedJob)loadedReportId=selectedJob;analysisDirty=false;renderQuickSettings();await refresh();workspaceReady=true;
 if(savedState.has_saved_state&&workspaceSaveStatus!=='error')workspaceSaveStatus='saved';renderWorkspaceStatus();translateUI();
 if(savedState.warning)notice(t('工作区文件无法完整读取，已保留恢复副本。','The workspace could not be fully read; a recovery copy was preserved.')+' '+savedState.warning);
 if(savedState.initial_report_id)await restoreJob(savedState.initial_report_id);
 else if(!savedState.has_saved_state&&(Object.keys(legacy).length||localRead('ycscite-language'))){await rememberSettings(settings);await rememberMetadata({inputs:[...inputs],view:selectedKey,report_id:selectedJob,output:$('output').value,download_logo:$('download-logo').checked});}
}
