function openSettings(batch=false){batchMode=batch;settingsDraft=structuredClone(settings);settingsTab=batch?'output':'data';settingsForm();$('apply-settings').textContent=batch?t('开始批量导出','Start batch export'):t('应用设置','Apply settings');$('chart-options').parentElement.hidden=!batch&&settingsTab==='output';$('settings-dialog').showModal();}
